function DashboardPage() { const q = useGetDashboard(); const rq = useListRecommendations(); const d = useFallback(q.data as any, demoDashboard) as any; const liveRecommendation = (rq.data as any)?.[0]; if (liveRecommendation) d.recommendation = liveRecommendation; const stats = d.stats; return <><PageHead eyebrow="Monday, 9:14 AM" title={d.greeting} subtitle={d.subtitle} action={<Link href="/practice" className="inline-flex items-center gap-2 rounded-full bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground" data-testid="link-dashboard-practice">Start a session <ArrowRight className="h-4 w-4" /></Link>} />{q.isLoading && !q.data ? <Loading /> : <div className="stagger space-y-7"><Card className="overflow-hidden"><div className="grid gap-7 p-6 md:grid-cols-[1fr_230px] md:p-8"><div><div className="flex items-center gap-2"><Badge tone="coral">Your next best move</Badge><span className="mono text-[10px] text-muted-foreground">{d.recommendation.recommendedMinutes} MIN</span></div><h2 className="display mt-5 text-4xl">{d.recommendation.title}</h2><p className="mt-2 max-w-xl text-sm leading-6 text-muted-foreground">{d.recommendation.reason}</p><div className="mt-6 flex flex-wrap items-center gap-3"><Link href="/practice" className="inline-flex items-center gap-2 rounded-full bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground" data-testid="link-recommendation-action">Take on {d.recommendation.questionCount} questions <ArrowRight className="h-4 w-4" /></Link><span className="text-xs text-muted-foreground"><Zap className="mr-1 inline h-3.5 w-3.5 text-accent-foreground" /> {d.recommendation.difficulty} set</span></div></div><div className="flex items-center justify-center rounded-2xl bg-secondary/60 p-5"><div className="ring-progress grid h-36 w-36 place-items-center rounded-full" style={{ '--progress': `${d.concepts[0]?.masteryScore ?? 42}%` } as any}><div className="grid h-28 w-28 place-items-center rounded-full bg-card text-center"><p className="mono text-3xl text-primary">{d.concepts[0]?.masteryScore ?? 42}%</p><p className="text-[10px] uppercase tracking-[.1em] text-muted-foreground">mastery</p></div></div></div></div><div className="flex items-center justify-between border-t border-border bg-muted/40 px-6 py-3 text-xs text-muted-foreground"><span>Concept focus: <strong className="text-foreground">{d.recommendation.concept}</strong></span><Link href="/weaknesses" className="font-semibold text-primary" data-testid="link-dashboard-why">Why this?</Link></div></Card><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><Stat icon={Clock3} value={`${stats.weeklyMinutes}m`} label="study this week" note={`${stats.weeklyGoal - stats.weeklyMinutes}m to goal`} /><Stat icon={Flame} value={stats.streak} label="day streak" note="Keep the thread going" /><Stat icon={Brain} value={stats.questionsAnswered} label="questions answered" note="Across 6 sessions" /><Stat icon={TrendingUp} value={`${stats.overallMastery}%`} label="overall mastery" note="+8.4% this week" /></div><div className="grid gap-7 lg:grid-cols-[1.2fr_.8fr]"><Card className="p-6"><div className="flex items-start justify-between"><div><p className="mono text-[10px] uppercase tracking-[.18em] text-primary">Keep moving</p><h3 className="mt-2 text-xl font-bold">Recent materials</h3></div><Link href="/materials" className="text-sm font-semibold text-primary" data-testid="link-dashboard-materials">View library</Link></div><div className="mt-5 divide-y divide-border">{d.recentMaterials.slice(0, 3).map((m: any) => <Link href={`/materials/${m.id}`} key={m.id} className="flex items-center gap-4 py-4 first:pt-0 last:pb-0" data-testid={`link-recent-material-${m.id}`}><div className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-secondary text-primary"><FileText className="h-4 w-4" /></div><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{m.title}</p><p className="mt-1 text-xs text-muted-foreground">{m.subjectName} · {m.concepts} concepts</p></div><ChevronRight className="h-4 w-4 text-muted-foreground" /></Link>)}</div></Card><Card className="p-6"><div className="flex items-start justify-between"><div><p className="mono text-[10px] uppercase tracking-[.18em] text-primary">Your map</p><h3 className="mt-2 text-xl font-bold">Concepts to watch</h3></div><Link href="/weaknesses" className="text-sm font-semibold text-primary" data-testid="link-dashboard-weaknesses">See all</Link></div><div className="mt-5 space-y-4">{d.concepts.slice(0, 3).map((c: any) => <ConceptRow c={c} key={c.id} />)}</div></Card></div></div>}</>; }
function Stat({ icon: Icon, value, label, note }: any) { return <Card className="p-5"><Icon className="h-4 w-4 text-primary" /><p className="mono mt-4 text-3xl">{value}</p><p className="mt-1 text-sm font-semibold">{label}</p><p className="mt-1 text-xs text-muted-foreground">{note}</p></Card>; }
function ConceptRow({ c }: any) { return <Link href={`/concepts/${c.id}`} className="block" data-testid={`link-concept-${c.id}`}><div className="mb-2 flex justify-between text-sm"><span className="font-semibold">{c.name}</span><span className="mono text-xs text-muted-foreground">{c.masteryScore}%</span></div><ProgressBar value={c.masteryScore} color={c.masteryScore < 50 ? 'bg-accent' : 'bg-primary'} /></Link>; }

function SubjectsPage() { const q = useListSubjects(); const create = useCreateSubject(); const client = useQueryClient(); const [adding, setAdding] = useState(false); const [name, setName] = useState(''); const [desc, setDesc] = useState(''); const subjects = useFallback(q.data as any, demoSubjects) as any[]; const submit = () => { if (!name.trim()) return; create.mutate({ data: { name, description: desc, color: '#3d8f76' } }, { onSuccess: () => { client.invalidateQueries({ queryKey: ['/api/subjects'] }); setName(''); setDesc(''); setAdding(false); } }); }; return <><PageHead eyebrow="Your curriculum" title="Subjects" subtitle="A home for every thread you are learning." action={<Button onClick={() => setAdding(true)} data-testid="button-add-subject"><Plus className="h-4 w-4" /> Add subject</Button>} />{adding && <Card className="mb-6 p-6"><div className="flex items-center justify-between"><h3 className="font-bold">Create a subject</h3><button onClick={() => setAdding(false)} aria-label="Close form" data-testid="button-close-subject-form"><X className="h-4 w-4" /></button></div><div className="mt-5 grid gap-4 md:grid-cols-2"><input value={name} onChange={e => setName(e.target.value)} placeholder="e.g. Organic chemistry" className="rounded-xl border border-input bg-background px-4 py-3 text-sm outline-none focus:ring-2 focus:ring-ring" data-testid="input-subject-name" /><input value={desc} onChange={e => setDesc(e.target.value)} placeholder="What are you exploring?" className="rounded-xl border border-input bg-background px-4 py-3 text-sm outline-none focus:ring-2 focus:ring-ring" data-testid="input-subject-description" /></div><Button onClick={submit} disabled={!name.trim() || create.isPending} className="mt-4" data-testid="button-submit-subject">{create.isPending ? 'Creating…' : 'Create subject'}</Button></Card>}{q.isError && <ErrorState retry={() => q.refetch()} />}{!subjects.length ? <Empty icon={BookOpen} title="Start with a subject" body="Subjects keep your material and practice sessions in a useful orbit." action={<Button onClick={() => setAdding(true)}>Add your first subject</Button>} /> : <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">{subjects.map((s: any) => <Link href="/materials" key={s.id} className="group" data-testid={`card-subject-${s.id}`}><Card className="h-full overflow-hidden p-6 transition-transform duration-200 group-hover:-translate-y-1"><div className="mb-8 flex items-start justify-between"><span className="h-3 w-3 rounded-full" style={{ background: s.color }} /><MoreHorizontal className="h-4 w-4 text-muted-foreground" /></div><h3 className="display text-3xl">{s.name}</h3><p className="mt-2 min-h-12 text-sm leading-6 text-muted-foreground">{s.description}</p><div className="mt-7 flex items-center justify-between border-t border-border pt-4 text-xs"><span className="text-muted-foreground">{s.materialCount} materials</span><span className="font-semibold text-primary">Open subject <ArrowRight className="ml-1 inline h-3.5 w-3.5" /></span></div></Card></Link>)}</div>}</>; }

function MaterialsPage() { const q = useListMaterials(); const sq = useListSubjects(); const create = useCreateMaterial(); const del = useDeleteMaterial(); const client = useQueryClient(); const [search, setSearch] = useState(''); const [add, setAdd] = useState(false); const [title, setTitle] = useState(''); const [text, setText] = useState(''); const [subjectId, setSubjectId] = useState('biology'); const materials = useFallback(q.data as any, demoMaterials) as any[]; const subjects = useFallback(sq.data as any, demoSubjects) as any[]; const filtered = materials.filter(m => `${m.title} ${m.subjectName}`.toLowerCase().includes(search.toLowerCase())); const submit = () => { if (!title.trim()) return; create.mutate({ data: { title, subjectId, fileType: 'notes', pastedText: text } }, { onSuccess: () => { client.invalidateQueries({ queryKey: ['/api/materials'] }); setTitle(''); setText(''); setAdd(false); } }); }; return <><PageHead eyebrow="Your source material" title="Materials" subtitle="Everything Recall uses to build your study map." action={<Button onClick={() => setAdd(true)} data-testid="button-add-material"><Plus className="h-4 w-4" /> Add material</Button>} />{add && <Card className="mb-6 p-6"><div className="flex items-center justify-between"><div><h3 className="font-bold">Add study material</h3><p className="mt-1 text-sm text-muted-foreground">Paste the useful parts. Recall will find the concepts.</p></div><button onClick={() => setAdd(false)} aria-label="Close material form" data-testid="button-close-material-form"><X className="h-4 w-4" /></button></div><div className="mt-5 grid gap-4"><input value={title} onChange={e => setTitle(e.target.value)} placeholder="Title your notes" className="rounded-xl border border-input bg-background px-4 py-3 text-sm outline-none focus:ring-2 focus:ring-ring" data-testid="input-material-title" /><div className="grid gap-4 md:grid-cols-2"><select value={subjectId} onChange={e => setSubjectId(e.target.value)} className="rounded-xl border border-input bg-background px-4 py-3 text-sm outline-none" data-testid="select-material-subject">{subjects.map((s: any) => <option key={s.id} value={s.id}>{s.name}</option>)}</select><button className="flex items-center justify-center gap-2 rounded-xl border border-dashed border-primary/40 bg-primary/5 px-4 py-3 text-sm font-semibold text-primary" data-testid="button-upload-material"><Upload className="h-4 w-4" /> Upload a file <span className="text-xs font-normal text-muted-foreground">(demo)</span></button></div><textarea value={text} onChange={e => setText(e.target.value)} placeholder="Or paste your lecture notes here…" rows={5} className="resize-none rounded-xl border border-input bg-background px-4 py-3 text-sm outline-none focus:ring-2 focus:ring-ring" data-testid="textarea-material-text" /></div><Button onClick={submit} disabled={!title.trim() || create.isPending} className="mt-4" data-testid="button-submit-material">{create.isPending ? 'Processing…' : 'Add to Recall'}</Button></Card>}<div className="mb-5 flex items-center gap-3"><div className="relative max-w-md flex-1"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search materials or subjects" className="w-full rounded-full border border-input bg-card py-3 pl-10 pr-4 text-sm outline-none focus:ring-2 focus:ring-ring" data-testid="input-search-materials" /></div><span className="hidden text-xs text-muted-foreground sm:block">{filtered.length} of {materials.length}</span></div>{!filtered.length ? <Empty icon={FileText} title={search ? 'No matches here' : 'Your library is waiting'} body={search ? 'Try a different title or subject.' : 'Add your first notes, then turn them into practice.'} action={!search && <Button onClick={() => setAdd(true)}>Add material</Button>} /> : <div className="grid gap-4 md:grid-cols-2">{filtered.map((m: any) => <Card key={m.id} className="group p-5" data-testid={`card-material-${m.id}`}><div className="flex gap-4"><div className="grid h-11 w-11 shrink-0 place-items-center rounded-xl bg-secondary text-primary"><FileText className="h-5 w-5" /></div><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-2"><Link href={`/materials/${m.id}`} className="truncate font-bold hover:text-primary" data-testid={`link-material-${m.id}`}>{m.title}</Link><button onClick={() => { if (confirm('Remove this material?')) { del.mutate({ id: m.id }, { onSuccess: () => client.invalidateQueries({ queryKey: ['/api/materials'] }) }); } }} className="rounded-full p-1 text-muted-foreground opacity-0 hover:bg-destructive/10 hover:text-destructive group-hover:opacity-100" aria-label={`Delete ${m.title}`} data-testid={`button-delete-material-${m.id}`}><Trash2 className="h-4 w-4" /></button></div><p className="mt-1 text-xs text-muted-foreground">{m.subjectName} · added {m.createdAt}</p><p className="mt-4 line-clamp-2 text-sm leading-6 text-muted-foreground">{m.excerpt}</p><div className="mt-5 flex items-center gap-2"><Badge tone={m.processingStatus === 'ready' ? 'green' : 'amber'}>{m.processingStatus}</Badge><span className="text-xs text-muted-foreground">{m.concepts} concepts</span><span className="text-xs text-muted-foreground">·</span><span className="text-xs text-muted-foreground">{m.sessions} sessions</span></div></div></div></Card>)}</div>}</>; }

function MaterialDetailPage() { const { id = 'm1' } = useParams(); const q = useGetMaterial(id); const m = useFallback(q.data as any, demoMaterials.find(x => x.id === id) ?? demoMaterials[0]) as any; return <><Link href="/materials" className="mb-6 inline-flex items-center gap-2 text-sm font-semibold text-muted-foreground hover:text-foreground" data-testid="link-back-materials">← Back to materials</Link><PageHead eyebrow={m.subjectName} title={m.title} subtitle={m.excerpt} action={<Link href="/practice" className="inline-flex items-center gap-2 rounded-full bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground" data-testid="link-practice-material">Practice this material <ArrowRight className="h-4 w-4" /></Link>} />{q.isLoading && !q.data ? <Loading /> : <div className="grid gap-6 lg:grid-cols-[1fr_330px]"><Card className="p-6 md:p-8"><div className="flex items-center justify-between border-b border-border pb-5"><div><p className="mono text-[10px] uppercase tracking-[.18em] text-primary">Concept map</p><h2 className="mt-2 text-xl font-bold">What this material covers</h2></div><Badge tone="green">{m.processingStatus}</Badge></div><div className="mt-6 space-y-5">{demoConcepts.filter(c => c.subjectId === m.subjectId || m.id === 'm1').map(c => <ConceptRow c={c} key={c.id} />)}</div><div className="mt-8 rounded-xl bg-secondary/50 p-5"><p className="mono text-[10px] uppercase tracking-[.18em] text-primary">Source excerpt</p><p className="mt-3 text-sm leading-7 text-foreground/80">“{m.excerpt}”</p></div></Card><Card className="h-fit p-6"><p className="mono text-[10px] uppercase tracking-[.18em] text-primary">At a glance</p><div className="mt-5 space-y-5"><Mini label="Concepts found" value={m.concepts || 8} /><Mini label="Practice sessions" value={m.sessions} /><Mini label="Last studied" value={m.lastStudied ?? 'Not yet'} /></div><Link href="/practice" className="mt-7 flex w-full items-center justify-center rounded-full border border-border px-4 py-2.5 text-sm font-bold hover:bg-muted" data-testid="link-detail-practice">Build a practice set</Link></Card></div>}</>; }
function Mini({ label, value }: any) { return <div className="flex items-center justify-between border-b border-border pb-3 text-sm last:border-0"><span className="text-muted-foreground">{label}</span><span className="font-bold">{value}</span></div>; }

function PracticePage() { const subjectsQuery = useListSubjects(); const materialsQuery = useListMaterials(); const subjects = (subjectsQuery.data as any[]) ?? []; const materials = (materialsQuery.data as any[]) ?? []; const create = useCreatePractice(); const weakness = useCreateWeaknessPractice(); const [, setLocation] = useLocation(); const [mode, setMode] = useState('focus'); const [subject, setSubject] = useState(''); const [minutes, setMinutes] = useState(12); const [count, setCount] = useState(6); const [error, setError] = useState(''); const start = () => { setError(''); if (mode === 'weakness') weakness.mutate({ data: { conceptIds: [], durationMinutes: minutes } }, { onSuccess: s => setLocation(`/practice/${s.id}`), onError: () => setError('Recall could not build a practice session from your persisted study data.') }); else create.mutate({ data: { subjectId: subject || null, materialId: null, durationMinutes: minutes, difficulty: mode === 'review' ? 'review' : 'focused', questionCount: count } }, { onSuccess: s => setLocation(`/practice/${s.id}`), onError: () => setError('Recall could not build a practice session from your persisted study data.') }); }; if (subjectsQuery.isLoading || materialsQuery.isLoading) return <Loading />; if (subjectsQuery.isError || materialsQuery.isError) return <ErrorState retry={() => { subjectsQuery.refetch(); materialsQuery.refetch(); }} />; return <><PageHead eyebrow="Retrieval, not rereading" title="What should we practice?" subtitle="Choose a starting point. Recall will keep the session focused and show you what to do after." /><div className="grid gap-5 lg:grid-cols-3">{[{ id: 'focus', icon: Target, title: 'Focus my gaps', body: 'A short set built around the concepts where your understanding is thinnest.' }, { id: 'review', icon: BookOpen, title: 'Review a subject', body: 'Warm up a subject with a balanced mix of concepts and difficulty.' }, { id: 'weakness', icon: Zap, title: 'Target weaknesses', body: 'Go straight at persisted weak concepts.' }].map(({ id, icon: Icon, title, body }) => <button key={id} onClick={() => setMode(id)} className={`text-left ${mode === id ? 'ring-2 ring-primary' : ''}`} data-testid={`button-practice-mode-${id}`}><Card className={`h-full p-6 transition-transform hover:-translate-y-1 ${mode === id ? 'bg-primary/5' : ''}`}><div className="flex items-center justify-between"><div className="grid h-11 w-11 place-items-center rounded-xl bg-secondary text-primary"><Icon className="h-5 w-5" /></div>{mode === id && <span className="grid h-6 w-6 place-items-center rounded-full bg-primary text-primary-foreground"><Check className="h-3.5 w-3.5" /></span>}</div><h2 className="mt-8 text-xl font-bold">{title}</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">{body}</p></Card></button>)}</div><Card className="mt-6 max-w-3xl p-6 md:p-8"><div className="grid gap-6 md:grid-cols-2"><div><label className="text-xs font-bold uppercase tracking-[.12em] text-muted-foreground">Subject</label><select value={subject} onChange={e => setSubject(e.target.value)} disabled={mode === 'weakness'} className="mt-2 w-full rounded-xl border border-input bg-background px-4 py-3 text-sm" data-testid="select-practice-subject"><option value="">All subjects</option>{subjects.map((s: any) => <option key={s.id} value={s.id}>{s.name}</option>)}</select></div><div><label className="text-xs font-bold uppercase tracking-[.12em] text-muted-foreground">Material</label><select disabled className="mt-2 w-full rounded-xl border border-input bg-background px-4 py-3 text-sm opacity-70" data-testid="select-practice-material"><option>{mode === 'weakness' ? 'Selected by Recall' : `${materials.length} materials available`}</option></select></div></div><div className="mt-7 border-t border-border pt-6"><div className="flex items-center justify-between"><label className="text-xs font-bold uppercase tracking-[.12em] text-muted-foreground">Session length</label><span className="mono text-sm text-primary">{minutes} minutes</span></div><div className="mt-4 flex gap-2">{[8, 12, 20, 30].map(n => <button key={n} onClick={() => setMinutes(n)} className={`rounded-full border px-4 py-2 text-sm font-semibold ${minutes === n ? 'border-primary bg-primary text-primary-foreground' : 'border-border hover:bg-muted'}`} data-testid={`button-duration-${n}`}>{n}m</button>)}</div></div>{error && <p className="mt-5 rounded-xl bg-destructive/10 px-4 py-3 text-sm text-destructive">{error}</p>}<div className="mt-6 flex items-center justify-between"><p className="text-sm text-muted-foreground">{mode === 'weakness' ? 'Persisted weak concepts · adaptive questions' : `${count} questions · ${mode} difficulty`}</p><Button onClick={start} disabled={create.isPending || weakness.isPending || !materials.length} data-testid="button-start-practice">{create.isPending || weakness.isPending ? 'Building set…' : 'Start practice'} <ArrowRight className="h-4 w-4" /></Button></div></Card></>; }

function PracticeSessionPage() { const { id = '' } = useParams(); const q = useGetPractice(id, { query: { enabled: Boolean(id), queryKey: ['/api/practice', id] } } as any); const answer = useAnswerPractice(); const complete = useCompletePractice(); const [, setLocation] = useLocation(); const [index, setIndex] = useState(0); const [choice, setChoice] = useState(''); const [confidence, setConfidence] = useState('medium'); const [result, setResult] = useState<any>(null); if (q.isLoading) return <Loading label="Restoring your persisted practice session" />; if (q.isError || !q.data) return <ErrorState retry={() => q.refetch()} />; const session = q.data as any; const question = session.questions[index]; if (!question) return <Empty icon={Brain} title="No persisted questions" body="This session does not contain any questions from your study materials." action={<Link href="/practice" className="font-semibold text-primary">Back to practice</Link>} />; const options = question.type === 'true_false' ? ['True', 'False'] : question.options ?? []; const move = () => { setResult(null); setChoice(''); setConfidence('medium'); if (index + 1 < session.questions.length) setIndex(index + 1); else complete.mutate({ id }, { onSuccess: r => setLocation(`/results/${r.id}`) }); }; const next = () => { if (result) return move(); answer.mutate({ id, data: { questionId: question.id, answer: choice, confidence, responseTimeMs: 28000 } }, { onSuccess: setResult }); }; return <div className="mx-auto max-w-3xl"><div className="mb-8 flex items-center justify-between"><div><Link href="/practice" className="text-sm text-muted-foreground hover:text-foreground" data-testid="link-exit-practice">Exit practice</Link><p className="mt-3 font-bold">{session.title}</p></div><div className="text-right"><p className="mono text-xs text-primary">{String(index + 1).padStart(2, '0')} / {String(session.questions.length).padStart(2, '0')}</p><div className="mt-2 w-32"><ProgressBar value={(index / session.questions.length) * 100} /></div></div></div><Card className="p-6 md:p-10"><div className="flex flex-wrap items-center gap-2"><Badge tone="green">{session.subjectName}</Badge><Badge>{question.concept}</Badge><Badge tone="amber">{question.difficulty}</Badge></div><h1 className="display mt-8 text-4xl leading-tight md:text-5xl">{question.questionText}</h1><div className="mt-8 space-y-3">{question.type === 'short_answer' ? <input value={choice} onChange={e => setChoice(e.target.value)} placeholder="Type your answer…" className="w-full rounded-xl border border-input bg-background px-4 py-3 text-sm" data-testid="input-short-answer" /> : options.map((option: string, i: number) => <button key={option} onClick={() => setChoice(option)} className={`flex w-full items-center gap-4 rounded-xl border p-4 text-left text-sm transition-colors ${choice === option ? 'border-primary bg-primary/10' : 'border-border hover:bg-muted'}`} data-testid={`button-answer-option-${i}`}><span className={`grid h-7 w-7 shrink-0 place-items-center rounded-full border text-xs font-bold ${choice === option ? 'border-primary bg-primary text-primary-foreground' : 'border-border text-muted-foreground'}`}>{String.fromCharCode(65 + i)}</span>{option}</button>)}</div>{!result ? <div className="mt-8 border-t border-border pt-6"><div className="flex flex-wrap items-center justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[.12em] text-muted-foreground">How confident are you?</p><div className="mt-2 flex gap-2">{['low', 'medium', 'high'].map(c => <button key={c} onClick={() => setConfidence(c)} className={`rounded-full px-3 py-1.5 text-xs font-semibold ${confidence === c ? 'bg-secondary text-foreground' : 'text-muted-foreground hover:bg-muted'}`} data-testid={`button-confidence-${c}`}>{c}</button>)}</div></div><Button onClick={next} disabled={!choice.trim() || answer.isPending || complete.isPending} data-testid="button-submit-answer">{index + 1 === session.questions.length ? 'Finish session' : 'Lock answer'} <ArrowRight className="h-4 w-4" /></Button></div></div> : <div className={`mt-8 rounded-2xl p-5 ${result.isCorrect ? 'bg-primary/10' : 'bg-accent/15'}`}><div className="flex items-center gap-2 font-bold">{result.isCorrect ? <Check className="h-5 w-5 text-primary" /> : <Target className="h-5 w-5 text-accent-foreground" />}{result.isCorrect ? 'That holds up.' : 'This is the gap to repair.'}</div><p className="mt-3 text-sm leading-6">{result.explanation}</p><p className="mt-4 border-l-2 border-primary/40 pl-3 text-xs italic text-muted-foreground">“{result.sourceExcerpt}”</p><Button onClick={next} className="mt-5" data-testid="button-next-question">{index + 1 === session.questions.length ? 'See my results' : 'Next question'} <ArrowRight className="h-4 w-4" /></Button></div>}</Card></div>; }

function ResultsPage() { const { id = '' } = useParams(); const q = useGetPractice(id, { query: { enabled: Boolean(id), queryKey: ['/api/practice', id] } } as any); const create = useCreateWeaknessPractice(); const [, setLocation] = useLocation(); if (q.isLoading) return <Loading label="Restoring your persisted result" />; if (q.isError || !q.data?.results) return <ErrorState retry={() => q.refetch()} />; const r: any = q.data.results; return <><PageHead eyebrow="Session complete" title="You found the edge." subtitle="A good session does not make every answer right. It makes the next answer more useful." action={<Button onClick={() => create.mutate({ data: { conceptIds: r.weakConcepts ?? [], durationMinutes: 10 } }, { onSuccess: s => setLocation(`/practice/${s.id}`) })} data-testid="button-retest-results">Retest the gap <ArrowRight className="h-4 w-4" /></Button>} /><div className="grid gap-6 lg:grid-cols-[.8fr_1.2fr]"><Card className="flex flex-col items-center justify-center p-8 text-center"><div className="ring-progress grid h-48 w-48 place-items-center rounded-full" style={{ '--progress': `${r.score}%` } as any}><div className="grid h-36 w-36 place-items-center rounded-full bg-card"><span className="mono text-5xl text-primary">{r.score}</span><span className="text-xs text-muted-foreground">/ 100</span></div></div><p className="mt-6 text-sm font-semibold">A solid working understanding</p><p className="mt-2 max-w-xs text-sm leading-6 text-muted-foreground">You improved {r.improvement}% from your last attempt.</p></Card><div className="space-y-6"><Card className="p-6"><p className="mono text-[10px] uppercase tracking-[.18em] text-primary">The diagnosis</p><h2 className="display mt-3 text-3xl">Specific beats perfect.</h2><p className="mt-3 text-sm leading-7 text-muted-foreground">{r.diagnosis}</p><div className="mt-6 grid gap-3 sm:grid-cols-2"><ResultMetric label="Correct" value={`${r.correct}/${r.questionsAnswered}`} /><ResultMetric label="Avg. confidence" value={r.averageConfidence} /><ResultMetric label="Response time" value={r.averageResponseTime} /><ResultMetric label="Change" value={`+${r.improvement}%`} /></div></Card><div className="grid gap-4 sm:grid-cols-2"><Card className="p-5"><Badge tone="green">Holding strong</Badge><div className="mt-4 space-y-2">{(r.strongConcepts ?? []).map((x: string) => <p className="text-sm font-semibold" key={x}><Check className="mr-2 inline h-4 w-4 text-primary" />{x}</p>)}</div></Card><Card className="p-5"><Badge tone="coral">Next attention</Badge><div className="mt-4 space-y-2">{(r.needsAttention ?? []).map((x: string) => <Link href="/weaknesses" className="block text-sm font-semibold hover:text-primary" key={x} data-testid={`link-result-weakness-${x}`}><Target className="mr-2 inline h-4 w-4 text-accent-foreground" />{x}</Link>)}</div></Card></div></div></div></>; }
function ResultMetric({ label, value }: any) { return <div className="rounded-xl bg-muted/60 p-3"><p className="text-xs text-muted-foreground">{label}</p><p className="mono mt-1 text-lg">{value}</p></div>; }

function WeaknessesPage() { const q = useListConcepts(); const create = useCreateWeaknessPractice(); const [, setLocation] = useLocation(); const concepts = useFallback(q.data as any, demoConcepts) as any[]; const weak = concepts.filter(c => c.masteryScore < 65).sort((a, b) => a.masteryScore - b.masteryScore); return <><PageHead eyebrow="Your study map" title="Where understanding breaks" subtitle="Recall watches for the difference between recognizing an idea and being able to retrieve it." action={<Button onClick={() => create.mutate({ data: { conceptIds: weak.slice(0, 2).map(c => c.id), durationMinutes: 12 } }, { onSuccess: s => setLocation(`/practice/${s.id}`), onError: () => setLocation('/practice/demo') })} data-testid="button-practice-weaknesses"><Target className="h-4 w-4" /> Practice weak spots</Button>} /><div className="grid gap-6 lg:grid-cols-[1.2fr_.8fr]"><Card className="p-6 md:p-8"><div className="flex items-center justify-between"><div><p className="mono text-[10px] uppercase tracking-[.18em] text-primary">Needs attention</p><h2 className="mt-2 text-xl font-bold">{weak.length} concepts are asking for a return</h2></div><span className="mono text-4xl text-accent-foreground">02</span></div><div className="mt-7 space-y-6">{weak.map(c => <div key={c.id}><div className="mb-2 flex items-end justify-between"><div><Link href={`/concepts/${c.id}`} className="font-bold hover:text-primary" data-testid={`link-weakness-${c.id}`}>{c.name}</Link><p className="mt-1 text-xs text-muted-foreground">{c.subjectName} · {c.questionsAttempted} questions attempted</p></div><span className="mono text-sm">{c.masteryScore}%</span></div><ProgressBar value={c.masteryScore} color="bg-accent" /><p className="mt-2 text-xs text-muted-foreground">{c.masteryScore < 40 ? 'A fresh explanation and a short retest would help.' : 'Close to clicking. A few retrieval reps should settle this.'}</p></div>)}</div></Card><Card className="relative overflow-hidden bg-sidebar p-7 text-sidebar-foreground"><div className="absolute -right-12 -top-12 h-40 w-40 rounded-full border border-sidebar-primary/20" /><div className="absolute -right-4 -top-4 h-24 w-24 rounded-full border border-sidebar-primary/20" /><Sparkles className="h-5 w-5 text-sidebar-primary" /><h2 className="display mt-8 text-4xl">The useful miss</h2><p className="mt-4 text-sm leading-7 text-sidebar-foreground/70">Getting an answer wrong is not a verdict. It is a coordinate. This map turns that coordinate into your next session.</p><Link href="/mistakes" className="mt-8 inline-flex items-center gap-2 text-sm font-bold text-sidebar-primary" data-testid="link-review-mistakes">Review your misses <ArrowRight className="h-4 w-4" /></Link></Card></div><div className="mt-7"><h2 className="mb-4 text-xl font-bold">Developing nicely</h2><div className="grid gap-4 sm:grid-cols-2">{concepts.filter(c => c.masteryScore >= 65).map(c => <Card className="p-5" key={c.id}><ConceptRow c={c} /><p className="mt-4 text-xs text-muted-foreground">{c.sourceMaterial}</p></Card>)}</div></div></>; }

function ConceptPage() { const { id = 'c1' } = useParams(); const c: any = demoConcepts.find(x => x.id === id) ?? demoConcepts[0]; const create = useCreateWeaknessPractice(); const [, setLocation] = useLocation(); return <><Link href="/weaknesses" className="mb-6 inline-flex text-sm font-semibold text-muted-foreground" data-testid="link-back-weaknesses">← Back to map</Link><PageHead eyebrow={`${c.subjectName} · concept`} title={c.name} subtitle={`From ${c.sourceMaterial}. Recall is tracking how reliably this idea comes back when you need it.`} action={<Button onClick={() => create.mutate({ data: { conceptIds: [c.id], durationMinutes: 10 } }, { onSuccess: s => setLocation(`/practice/${s.id}`), onError: () => setLocation('/practice/demo') })} data-testid="button-practice-concept">Practice this concept <ArrowRight className="h-4 w-4" /></Button>} /><div className="grid gap-6 lg:grid-cols-[.8fr_1.2fr]"><Card className="p-7"><p className="mono text-[10px] uppercase tracking-[.18em] text-primary">Current mastery</p><div className="mt-5 flex items-end gap-3"><span className="display text-7xl">{c.masteryScore}</span><span className="mb-3 text-muted-foreground">/ 100</span></div><ProgressBar value={c.masteryScore} color={c.masteryScore < 50 ? 'bg-accent' : 'bg-primary'} /><div className="mt-7 space-y-4"><Mini label="Questions attempted" value={c.questionsAttempted} /><Mini label="Last practiced" value={c.lastPracticed ?? 'Not yet'} /><Mini label="Status" value={c.status.replace('_', ' ')} /></div></Card><Card className="p-7"><p className="mono text-[10px] uppercase tracking-[.18em] text-primary">A clearer explanation</p><h2 className="display mt-4 text-3xl">What to hold onto</h2><p className="mt-4 text-sm leading-7 text-muted-foreground">The electron transport chain creates a proton gradient. ATP synthase is the door that lets those protons flow back through, using the movement to attach phosphate to ADP.</p><div className="mt-7 rounded-xl bg-secondary/60 p-5"><p className="mono text-[10px] uppercase tracking-[.18em] text-primary">From your notes</p><p className="mt-3 text-sm leading-7">“The proton motive force drives the synthesis of ATP.”</p></div></Card></div></>; }

function ProgressPage() { const q = useGetProgress(); const p: any = useFallback(q.data as any, demoProgress); const max = Math.max(...p.weekly.map((x: any) => x.minutes), 1); return <><PageHead eyebrow="The long view" title="Progress" subtitle="Notice the trend, then return to the idea that still feels a little slippery." /><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><Stat icon={TrendingUp} value={`${p.overallMastery}%`} label="overall mastery" note={`+${p.changeThisWeek}% this week`} /><Stat icon={Check} value={`${p.accuracy}%`} label="answer accuracy" note="Across all sessions" /><Stat icon={Brain} value={`${p.confidence}%`} label="confidence" note="Honesty is useful here" /><Stat icon={Clock3} value={`${p.studyMinutes}m`} label="study time" note={`${p.questionsAnswered} questions`} /></div><div className="mt-7 grid gap-6 lg:grid-cols-[1.2fr_.8fr]"><Card className="p-6 md:p-8"><div className="flex items-center justify-between"><div><p className="mono text-[10px] uppercase tracking-[.18em] text-primary">This week</p><h2 className="mt-2 text-xl font-bold">Your study rhythm</h2></div><span className="text-sm text-muted-foreground">82 / 120 min</span></div><div className="mt-10 flex h-52 items-end justify-between gap-3">{p.weekly.map((d: any) => <div className="flex h-full flex-1 flex-col items-center justify-end gap-3" key={d.day}><div className="w-full max-w-10 rounded-t-lg bg-primary/80 transition-all" style={{ height: `${Math.max(d.minutes ? 12 : 3, (d.minutes / max) * 78)}%` }} title={`${d.minutes} minutes`} /><span className="mono text-[10px] text-muted-foreground">{d.day}</span></div>)}</div></Card><Card className="p-6 md:p-8"><p className="mono text-[10px] uppercase tracking-[.18em] text-primary">By concept</p><h2 className="mt-2 text-xl font-bold">Where to spend time</h2><div className="mt-6 space-y-5">{p.concepts.map((c: any) => <ConceptRow c={c} key={c.id} />)}</div></Card></div></>; }

function MistakesPage() { const q = useListMistakes(); const mistakes = useFallback(q.data as any, demoMistakes) as any[]; return <><PageHead eyebrow="Your retrieval trail" title="Mistakes worth revisiting" subtitle="These are not failures to hide. They are the shortest path to a more durable answer." action={<Link href="/practice" className="inline-flex items-center gap-2 rounded-full border border-border bg-card px-4 py-2.5 text-sm font-bold" data-testid="link-mistakes-practice">Practice again <ArrowRight className="h-4 w-4" /></Link>} />{!mistakes.length ? <Empty icon={Check} title="Nothing to untangle" body="Answer a few questions and Recall will keep track of the useful misses." /> : <div className="space-y-4">{mistakes.map((m, i) => <Card className="p-6" key={m.id} data-testid={`card-mistake-${m.id}`}><div className="flex gap-4"><div className="mono text-sm text-accent-foreground">0{i + 1}</div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center justify-between gap-2"><Badge tone="coral">{m.concept}</Badge><span className="text-xs text-muted-foreground">confidence: {m.confidence}</span></div><h2 className="mt-4 text-lg font-bold">{m.question}</h2><div className="mt-5 grid gap-3 md:grid-cols-2"><div className="rounded-xl bg-accent/10 p-4"><p className="text-[10px] font-bold uppercase tracking-[.12em] text-muted-foreground">Your answer</p><p className="mt-2 text-sm">{m.userAnswer}</p></div><div className="rounded-xl bg-primary/10 p-4"><p className="text-[10px] font-bold uppercase tracking-[.12em] text-primary">Better answer</p><p className="mt-2 text-sm">{m.correctAnswer}</p></div></div><p className="mt-5 text-sm leading-6 text-muted-foreground">{m.explanation}</p><p className="mt-4 border-l-2 border-border pl-3 text-xs italic text-muted-foreground">“{m.sourceExcerpt}”</p></div></div></Card>)}</div>}</>; }

function SettingsPage() { const [saved, setSaved] = useState(false); return <><PageHead eyebrow="Your preferences" title="Settings" subtitle="Make Recall fit the way your brain already works." /><div className="max-w-2xl space-y-5"><Card className="p-6"><h2 className="text-lg font-bold">Study preferences</h2><div className="mt-6 space-y-5"><Toggle label="Daily study nudge" body="A quiet reminder when your best study window opens." on data-testid="toggle-study-nudge" /><Toggle label="Show confidence check" body="Ask how sure you felt after every answer." on data-testid="toggle-confidence" /><Toggle label="Reduced motion" body="Keep transitions subtle across the workspace." data-testid="toggle-motion" /></div></Card><Card className="p-6"><h2 className="text-lg font-bold">Profile</h2><div className="mt-5 grid gap-4 sm:grid-cols-2"><label className="text-xs font-bold text-muted-foreground">Name<input defaultValue="Maya Chen" className="mt-2 w-full rounded-xl border border-input bg-background px-4 py-3 text-sm" data-testid="input-profile-name" /></label><label className="text-xs font-bold text-muted-foreground">Email<input defaultValue="maya@example.com" className="mt-2 w-full rounded-xl border border-input bg-background px-4 py-3 text-sm" data-testid="input-profile-email" /></label></div><Button onClick={() => { setSaved(true); setTimeout(() => setSaved(false), 1800); }} className="mt-5" data-testid="button-save-settings">{saved ? 'Saved' : 'Save changes'}</Button></Card></div></>; }
function Toggle({ label, body, on = false, ...props }: any) { const [active, setActive] = useState(on); return <div className="flex items-center justify-between gap-4"><div><p className="text-sm font-semibold">{label}</p><p className="mt-1 text-xs leading-5 text-muted-foreground">{body}</p></div><button onClick={() => setActive(!active)} className={`relative h-6 w-11 shrink-0 rounded-full transition-colors ${active ? 'bg-primary' : 'bg-muted'}`} aria-label={`Toggle ${label}`} data-testid={props['data-testid'] ?? 'toggle-setting'}><span className={`absolute top-1 h-4 w-4 rounded-full bg-card transition-transform ${active ? 'translate-x-6' : 'translate-x-1'}`} /></button></div>; }

function BillingPage() { const q = useGetSubscription(); const checkout = useCreateCheckout(); const s: any = useFallback(q.data as any, { plan: 'free', status: 'active', sessionsUsed: 6, sessionsLimit: 10, materialsUsed: 7, materialsLimit: 10, resetDate: 'March 31, 2025' }); const upgrade = () => checkout.mutate({ data: { interval: 'monthly' } }, { onSuccess: r => { if ((r as any).url) window.location.href = (r as any).url; } }); return <><PageHead eyebrow="Your workspace" title="Plan & usage" subtitle="Keep an eye on your study runway. Upgrade when the limits get in the way, not before." /><Card className="max-w-3xl overflow-hidden"><div className="flex flex-col justify-between gap-5 bg-sidebar p-7 text-sidebar-foreground sm:flex-row sm:items-end"><div><Badge tone="green">{s.plan} plan</Badge><h2 className="display mt-4 text-4xl">Enough room to build a habit.</h2></div><Button onClick={upgrade} className="bg-sidebar-primary text-sidebar-primary-foreground" data-testid="button-upgrade-plan">{checkout.isPending ? 'Opening checkout…' : 'Upgrade to Plus'}</Button></div><div className="grid gap-6 p-7 sm:grid-cols-2"><Usage label="Practice sessions" used={s.sessionsUsed} limit={s.sessionsLimit} /><Usage label="Study materials" used={s.materialsUsed} limit={s.materialsLimit} /></div><div className="border-t border-border px-7 py-4 text-xs text-muted-foreground">Limits reset {s.resetDate}. Need more room? <Link href="/pricing" className="font-semibold text-primary" data-testid="link-billing-pricing">Compare plans</Link></div></Card></>; }
function Usage({ label, used, limit }: any) { return <div><div className="flex justify-between text-sm"><span className="font-semibold">{label}</span><span className="mono text-xs">{used} / {limit}</span></div><ProgressBar value={(used / limit) * 100} /><p className="mt-2 text-xs text-muted-foreground">{limit - used} remaining this cycle</p></div>; }

function PricingPage() { const checkout = useCreateCheckout(); const buy = () => checkout.mutate({ data: { interval: 'monthly' } }); return <div className="min-h-[100dvh] bg-background text-foreground"><header className="mx-auto flex max-w-6xl items-center justify-between px-5 py-6 md:px-8"><Brand /><Link href="/dashboard" className="text-sm font-semibold text-muted-foreground hover:text-foreground" data-testid="link-pricing-workspace">Back to workspace</Link></header><main className="mx-auto max-w-5xl px-5 py-14 md:px-8 md:py-20"><div className="text-center"><Badge tone="green">Simple by design</Badge><h1 className="display mx-auto mt-5 max-w-2xl text-6xl leading-[.95]">Pay for more practice,<br /><em className="text-primary">not more noise.</em></h1><p className="mx-auto mt-5 max-w-lg text-sm leading-6 text-muted-foreground">Start with a generous free workspace. Upgrade when Recall becomes part of how you study.</p></div><div className="mt-14 grid gap-5 md:grid-cols-2"><Plan name="Free" price="$0" body="A thoughtful place to start." features={['10 practice sessions / month', '10 study materials', 'Concept mastery map', 'Mistake review']} /><Plan name="Plus" price="$8" body="For the student building momentum." features={['Unlimited practice sessions', 'Unlimited study materials', 'Targeted weakness sessions', 'Progress trends and insights']} featured onClick={buy} pending={checkout.isPending} /></div><p className="mt-8 text-center text-xs text-muted-foreground"><ShieldCheck className="mr-1 inline h-3.5 w-3.5 text-primary" /> Cancel anytime · Secure checkout · Your notes remain private</p></main></div>; }
function Plan({ name, price, body, features, featured, onClick, pending }: any) { return <Card className={`p-7 md:p-9 ${featured ? 'border-primary bg-primary/5 ring-1 ring-primary/30' : ''}`}><div className="flex items-center justify-between"><h2 className="text-xl font-bold">{name}</h2>{featured && <Badge tone="coral">Most useful</Badge>}</div><p className="mt-2 text-sm text-muted-foreground">{body}</p><p className="mt-8"><span className="display text-6xl">{price}</span><span className="text-sm text-muted-foreground"> / month</span></p><div className="my-8 space-y-3 border-t border-border pt-7">{features.map((f: string) => <p className="text-sm" key={f}><Check className="mr-2 inline h-4 w-4 text-primary" />{f}</p>)}</div>{featured ? <Button onClick={onClick} className="w-full" data-testid="button-pricing-upgrade">{pending ? 'Opening checkout…' : 'Choose Plus'}</Button> : <Link href="/signup" className="flex w-full justify-center rounded-full border border-border px-4 py-2.5 text-sm font-bold hover:bg-muted" data-testid="link-pricing-free">Start free</Link>}</Card>; }

function AuthPage({ signup = false }: { signup?: boolean }) {
  const [, setLocation] = useLocation();
  const client = useQueryClient();
  const [email, setEmail] = useState('');
  const [name, setName] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [pending, setPending] = useState(false);
  const submit = async () => {
    setError('');
    setPending(true);
    try {
      const response = await fetch(`/api/auth/${signup ? 'signup' : 'login'}`, {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(signup ? { name, email, password } : { email, password }),
      });
      const body = await response.json().catch(() => ({}));
      if (!response.ok) {
        setError(body.error ?? 'We could not sign you in. Check your details and try again.');
        return;
      }
      await client.invalidateQueries({ queryKey: ['/api/auth/session'] });
      setLocation('/dashboard');
    } catch {
      setError('We could not reach Recall. Please try again.');
    } finally {
      setPending(false);
    }
  };
  return <div className="grid min-h-[100dvh] bg-background text-foreground md:grid-cols-[.8fr_1.2fr]"><div className="hidden bg-sidebar p-10 text-sidebar-foreground md:flex md:flex-col md:justify-between"><Brand light /><div><p className="mono text-[10px] uppercase tracking-[.2em] text-sidebar-primary">A calmer study loop</p><h1 className="display mt-5 max-w-sm text-6xl leading-[.9]">The next answer is closer than you think.</h1><p className="mt-6 max-w-sm text-sm leading-6 text-sidebar-foreground/65">Recall turns your own material into a map you can actually use.</p></div><p className="text-xs text-sidebar-foreground/40">Private by default. Useful by design.</p></div><div className="flex items-center justify-center p-6"><div className="w-full max-w-md"><div className="mb-12 md:hidden"><Brand /></div><p className="mono text-[10px] uppercase tracking-[.2em] text-primary">{signup ? 'Start your workspace' : 'Welcome back'}</p><h1 className="display mt-3 text-5xl">{signup ? 'Study with a clearer head.' : 'Pick up the thread.'}</h1><p className="mt-3 text-sm text-muted-foreground">{signup ? 'Your notes are the beginning. Recall helps with the next move.' : 'Your study map is waiting where you left it.'}</p><div className="mt-9 space-y-4"><label className="block text-xs font-bold text-muted-foreground">Email<input type="email" value={email} onChange={event => setEmail(event.target.value)} placeholder="you@example.com" className="mt-2 w-full rounded-xl border border-input bg-card px-4 py-3.5 text-sm outline-none focus:ring-2 focus:ring-ring" data-testid="input-auth-email" /></label>{signup && <label className="block text-xs font-bold text-muted-foreground">Name<input value={name} onChange={event => setName(event.target.value)} placeholder="Your name" className="mt-2 w-full rounded-xl border border-input bg-card px-4 py-3.5 text-sm outline-none focus:ring-2 focus:ring-ring" data-testid="input-auth-name" /></label>}<label className="block text-xs font-bold text-muted-foreground">Password<input type="password" value={password} onChange={event => setPassword(event.target.value)} placeholder="At least 8 characters" className="mt-2 w-full rounded-xl border border-input bg-card px-4 py-3.5 text-sm outline-none focus:ring-2 focus:ring-ring" data-testid="input-auth-password" /></label>{error && <p className="rounded-xl bg-destructive/10 px-4 py-3 text-sm text-destructive" role="alert">{error}</p>}<Button onClick={submit} disabled={pending || !email || !password || (signup && !name)} className="mt-2 w-full py-3.5" data-testid="button-auth-submit">{pending ? 'Working…' : signup ? 'Create my workspace' : 'Continue'} <ArrowRight className="h-4 w-4" /></Button></div><p className="mt-7 text-center text-sm text-muted-foreground">{signup ? 'Already have an account? ' : 'New to Recall? '}<Link href={signup ? '/login' : '/signup'} className="font-bold text-primary" data-testid="link-auth-switch">{signup ? 'Sign in' : 'Create one'}</Link></p><p className="mt-10 text-center text-xs leading-5 text-muted-foreground">By continuing, you agree to our <Link href="/terms" className="underline">Terms</Link> and <Link href="/privacy" className="underline">Privacy Policy</Link>.</p></div></div></div>;
}

function TrustPage({ terms = false }: { terms?: boolean }) { return <div className="min-h-[100dvh] bg-background px-5 py-7 text-foreground md:px-8"><header className="mx-auto flex max-w-4xl items-center justify-between"><Brand /><Link href="/" className="text-sm font-semibold text-muted-foreground" data-testid="link-trust-home">Back home</Link></header><main className="mx-auto max-w-3xl py-20"><p className="mono text-[10px] uppercase tracking-[.2em] text-primary">{terms ? 'The fine print' : 'A note on trust'}</p><h1 className="display mt-4 text-6xl">{terms ? 'Terms of service' : 'Privacy, plainly'}</h1><p className="mt-5 text-sm leading-7 text-muted-foreground">Last updated February 28, 2025</p><div className="prose prose-stone mt-12 max-w-none text-foreground/80"><h2>{terms ? 'Use Recall to learn' : 'Your material is yours'}</h2><p>{terms ? 'Recall is a study workspace. Use it for your own learning, keep your account secure, and give your material the same care you would give your notebook.' : 'We use the notes you provide to generate your private study experience. We do not sell your material or use it to train a public model.'}</p><h2>{terms ? 'A useful, honest service' : 'What we keep'}</h2><p>{terms ? 'We work to keep Recall available and accurate, but generated questions can be imperfect. Check important facts against your course materials and ask your instructor when in doubt.' : 'Your account details, study materials, practice answers, and progress history are stored so Recall can show you a better next question. You can remove materials from your workspace at any time.'}</p><h2>{terms ? 'Questions' : 'Your choices'}</h2><p>For questions about this page or your data, reach out at <span className="font-semibold text-primary">hello@recall.study</span>. We will respond with a real person, not a maze.</p></div></main></div>; }

function AppRouter() { const protectedPage = (children: React.ReactNode) => <Protected><Shell>{children}</Shell></Protected>; return <Switch><Route path="/" component={Landing} /><Route path="/login"><AuthPage /></Route><Route path="/signup"><AuthPage signup /></Route><Route path="/pricing" component={PricingPage} /><Route path="/privacy"><TrustPage /></Route><Route path="/terms"><TrustPage terms /></Route><Route path="/dashboard">{protectedPage(<DashboardPage />)}</Route><Route path="/subjects">{protectedPage(<SubjectsPage />)}</Route><Route path="/materials">{protectedPage(<MaterialsPageV2 />)}</Route><Route path="/materials/:id">{protectedPage(<MaterialDetailPage />)}</Route><Route path="/practice">{protectedPage(<PracticePage />)}</Route><Route path="/practice/:id">{protectedPage(<PracticeSessionPage />)}</Route><Route path="/results/:id">{protectedPage(<ResultsPage />)}</Route><Route path="/weaknesses">{protectedPage(<WeaknessesPage />)}</Route><Route path="/concepts/:id">{protectedPage(<ConceptPage />)}</Route><Route path="/progress">{protectedPage(<ProgressPage />)}</Route><Route path="/mistakes">{protectedPage(<MistakesPage />)}</Route><Route path="/settings">{protectedPage(<SettingsPage />)}</Route><Route path="/billing">{protectedPage(<BillingPage />)}</Route><Route component={NotFound} /></Switch>; }
function App() { return <QueryClientProvider client={qc}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><ErrorBoundary><AppRouter /></ErrorBoundary></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;

function MaterialsPageV2() {
  const q = useListMaterials();
  const subjectsQuery = useListSubjects();
  const create = useCreateMaterial();
  const remove = useDeleteMaterial();
  const client = useQueryClient();
  const [adding, setAdding] = useState(false);
  const [title, setTitle] = useState('');
  const [text, setText] = useState('');
  const [subjectId, setSubjectId] = useState('');
  const [file, setFile] = useState<File | null>(null);
  const [error, setError] = useState('');
  const subjects = useFallback(subjectsQuery.data as any, demoSubjects) as any[];
  const materials = useFallback(q.data as any, demoMaterials) as any[];
  useEffect(() => { if (!subjectId && subjects[0]) setSubjectId(subjects[0].id); }, [subjectId, subjects]);
  useEffect(() => {
    if (materials.some((m: any) => String(m.processingStatus).toUpperCase() === 'PROCESSING')) {
      const timer = window.setInterval(() => q.refetch(), 1500);
      return () => window.clearInterval(timer);
    }
    return undefined;
  }, [materials, q]);
  const submit = async () => {
    if (!title.trim() || !subjectId || (!text.trim() && !file)) return;
    setError('');
    try {
      let data: any = { title: title.trim(), subjectId, fileType: 'text/plain', pastedText: text.trim() || undefined };
      if (file) {
        const extension = file.name.toLowerCase().split('.').pop();
        if (!['txt', 'pdf', 'docx', 'pptx'].includes(extension ?? '')) throw new Error('Supported files are TXT, PDF, DOCX, and PPTX.');
        if (file.size > 25 * 1024 * 1024) throw new Error('Files must be smaller than 25 MB.');
        const urlResponse = await fetch('/api/storage/uploads/request-url', { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name: file.name, size: file.size, contentType: file.type || 'application/octet-stream' }) });
        if (!urlResponse.ok) throw new Error('Could not prepare the private upload.');
        const upload = await urlResponse.json();
        const put = await fetch(upload.uploadURL, { method: 'PUT', headers: { 'Content-Type': file.type || 'application/octet-stream' }, body: file });
        if (!put.ok) throw new Error('The file upload failed.');
        data = { title: title.trim(), subjectId, fileType: file.type || `application/${extension}`, originalFileName: file.name, fileSize: file.size, storagePath: upload.objectPath };
      }
      create.mutate({ data }, { onSuccess: () => { client.invalidateQueries({ queryKey: ['/api/materials'] }); setTitle(''); setText(''); setFile(null); setAdding(false); }, onError: () => setError('Recall could not start processing this material.') });
    } catch (err) { setError(err instanceof Error ? err.message : 'Upload failed.'); }
  };
  const retry = async (id: string) => { await fetch(`/api/materials/${id}/retry`, { method: 'POST', credentials: 'include' }); await q.refetch(); };
  return <><PageHead eyebrow="Your source material" title="Materials" subtitle="Upload notes or paste text. Recall extracts the source before it builds your study map." action={<Button onClick={() => setAdding(true)}><Plus className="h-4 w-4" /> Add material</Button>} />
    {adding && <Card className="mb-6 p-6"><div className="flex items-center justify-between"><div><h3 className="font-bold">Add study material</h3><p className="mt-1 text-sm text-muted-foreground">TXT, PDF, DOCX, PPTX, or pasted text. Maximum 25 MB.</p></div><button onClick={() => setAdding(false)}><X className="h-4 w-4" /></button></div><div className="mt-5 grid gap-4"><input value={title} onChange={e => setTitle(e.target.value)} placeholder="Title your material" className="rounded-xl border border-input bg-background px-4 py-3 text-sm" /><select value={subjectId} onChange={e => setSubjectId(e.target.value)} className="rounded-xl border border-input bg-background px-4 py-3 text-sm">{subjects.map((s: any) => <option key={s.id} value={s.id}>{s.name}</option>)}</select><label className="flex cursor-pointer items-center gap-2 rounded-xl border border-dashed border-primary/40 bg-primary/5 px-4 py-3 text-sm font-semibold text-primary"><Upload className="h-4 w-4" />{file?.name ?? 'Choose a file'}<input type="file" accept=".txt,.pdf,.docx,.pptx" className="sr-only" onChange={e => setFile(e.target.files?.[0] ?? null)} /></label>{!file && <textarea value={text} onChange={e => setText(e.target.value)} placeholder="Or paste your lecture notes here…" rows={6} className="resize-none rounded-xl border border-input bg-background px-4 py-3 text-sm" />}</div>{error && <p className="mt-3 text-sm text-destructive">{error}</p>}<Button onClick={submit} disabled={create.isPending || !title.trim() || !subjectId || (!text.trim() && !file)} className="mt-4">{create.isPending ? 'Processing…' : 'Add to Recall'}</Button></Card>}
    <div className="grid gap-4 md:grid-cols-2">{materials.map((m: any) => <Card key={m.id} className="group p-5"><div className="flex items-start justify-between gap-3"><Link href={`/materials/${m.id}`} className="font-bold hover:text-primary">{m.title}</Link><button onClick={() => { if (confirm('Remove this material?')) remove.mutate({ id: m.id }, { onSuccess: () => client.invalidateQueries({ queryKey: ['/api/materials'] }) }); }}><Trash2 className="h-4 w-4 text-muted-foreground" /></button></div><p className="mt-1 text-xs text-muted-foreground">{m.subjectName} · {m.fileType}</p><p className="mt-4 line-clamp-3 text-sm leading-6 text-muted-foreground">{m.excerpt}</p><div className="mt-4 flex items-center gap-3"><Badge tone={String(m.processingStatus).toUpperCase() === 'READY' ? 'green' : String(m.processingStatus).toUpperCase() === 'FAILED' ? 'coral' : 'amber'}>{m.processingStatus}</Badge><span className="text-xs text-muted-foreground">{m.concepts} concepts</span>{String(m.processingStatus).toUpperCase() === 'FAILED' && <button onClick={() => retry(m.id)} className="ml-auto text-xs font-bold text-primary">Retry</button>}</div></Card>)}</div></>;
}